"""Human-readable ledger generated from the final score sheets only."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent
def dec(v,n=2):return f'{v:.{n}f}'.replace('.',',')
def main():
    r=json.loads((P/'results.json').read_bytes());t=json.loads((P/'transfer_results.json').read_bytes())
    names={'none':'Без записей, исходный порядок','recent':'Последние 4 места','cursor':'Циклический обход от текущей позиции','full':'Все проверенные места','raw':'Число прошлых обнаружений','rate':'Частота обнаружения на обследование','q_prior':'План Qwen по названию и комнате','q_shown':'План Qwen с правильными частотами','q_placebo':'План Qwen с данными другого предмета','q_fused':'План Qwen с формульной поправкой','all_static':'Все тренировочные комнаты','room_static':'Сходство видимых типов мест','all_miss':'Все комнаты и текущие промахи','room_miss':'Сходство комнат и текущие промахи'}
    s=['# Журнал поиска в ALFWorld','',
       'Задача агента — достичь цели в оригинальном текстовом симуляторе. Каждый эпизод начинается с публичного описания комнаты. Проверяются поиск предмета, доставка, пара предметов, свет, охлаждение, нагрев и мытьё в рамках шести официальных семейств. Абсолютный успех зависит от знания предметных действий и доступного интерфейса. У нас общая программа выполняет перенос и обработку, а политика памяти выбирает место следующего поиска. В основной серии доступно меню допустимых команд.','',
       'Из 39 тренировочных игр (30 планировок) собраны '+str(r['search_observations'])+' обследований за '+str(r['training_steps'])+' реальных действий. Предыдущие успехи и нулевые находки сохраняются как наблюдаемые числа. В исходном журнале для 24 последних обследований отсутствовал конечный список действий. Независимый повтор всех 39 игр восстановил его и проверил 875 из 875 записей. Для 134 unseen-игр всего четыре планировки, одна из них содержит 77 задач.','',
       '| Что помнит/читает агент | Успех из 134 | Среднее число шагов с начислением 50 за неудачу |','|---|---:|---:|']
    for a,v in r['all'].items():s.append(f"| {names[a]} | {v['won']} | {dec(v['mean_capped_steps'])} |")
    s+=['','Проверка механизма показала, что для кругового обхода достаточно текущей позиции. Независимо реализованное правило воспроизвело все 1 892 действия на 134 играх без отдельного указателя. Поэтому разница успеха между первым и третьим вариантами не измеряет выигрыш от хранения. Полный список и круговой обход решают одни и те же задачи, но используют разное число действий.','',
        'При одном и том же Qwen показ настоящих частот убрал 124 шага относительно пустой истории (12,76 против 13,69 в среднем). Для четырёх планировок разности сумм шагов составили −114, +6, +10 и −26. Описательный интервал при повторной выборке планировок для средней разности примерно от −1,46 до +0,42 шага. Отличие от подсказки о другом предмете сильнее, но и оно относится к четырём геометриям. Успех при всех четырёх способах планирования составил 134/134. Модель была вызвана 90 раз для уникальных сочетаний цели и видимых типов мест. Для всех выполненных планов разобраны все запрошенные категории.','',
        '## Перенос между планировками и обновление после промаха','',
        'Отдельно до ознакомления с исходами были заморожены четыре комбинации. Записи 39 тренировочных обследований комнат можно выбирать равномерно или взвешивать по сходству видимых типов мест, повышая четвёртую степень индекса Жаккара. Базовая частота стянута к общей частоте предмета. После неудачного осмотра очередного места можно снизить приоритет других мест этого же типа. Тестируется полный исходный unseen и дополнительный полный valid_seen с другими эпизодами. Только второй допускает знакомые тренировочные типы планировок на уровне самих комнат.','',
        '| Выбор опыта | Успех unseen | Шаги unseen | Успех seen | Шаги seen |','|---|---:|---:|---:|---:|']
    for a in ('full','rate','all_static','room_static','all_miss','room_miss'):
        x=t['valid_unseen']['all'][a];y=t['valid_seen']['all'][a]
        s.append(f"| {names[a]} | {x['won']}/{x['n']} | {dec(x['capped_steps_avg'])} | {y['won']}/{y['n']} | {dec(y['capped_steps_avg'])} |")
    for split in ('valid_unseen','valid_seen'):
        q=t[split]['contrasts']['room_miss-all_static']
        s+=['',f"Сочетание двух факторов против общей статической частоты, {split}: разница {dec(q['step_difference'])} шага на эпизод, парный интервал по планировкам [{dec(q['cluster_intervals'][1][0])}, {dec(q['cluster_intervals'][1][1])}], побед/поражений по достижению цели {q['W']}/{q['L']}."]
    s+=['','Все десять исходных вариантов и дополнительная проверка используют одну и ту же процедуру действий. Формула нормирования в rate отличается от сглаживания в четырёх факторных вариантах. Сравнение room_miss с all_static изолирует совместную поправку на комнату и текущие промахи. Для точного разбора двух факторов смотреть также room_miss−room_static, room_miss−all_miss, результаты отдельных планировок и семейств. Эпизоды со знакомыми планировками не заменяют внешнюю проверку на других симуляторах.','',
        'Параметры постановки MIRIX и условия корректного сравнения подробно приведены в ../mirix_reproduction_ru.md. Текстовый контроль доступности меню выделен в text_only. Каждый gzip в traces, planner_traces и transfer_traces содержит действия и ответы среды. Суммы и интервалы воспроизводятся score.py и transfer_score.py.']
    rates='В контроле rate используется (находки + 1) / (осмотры + 2). Его преимущество относительно сырых чисел объединяет нормирование и сглаживание. В valid_seen только 47 из 140 игр (23 из 76 планировок) действительно разделяют планировку с нашим набором из 39 train. Дополнительное разбиение и эффекты по нему сохранены в transfer_strata.json.'
    s.extend(['',rates,'','Метрика повторных осмотров в исходных таблицах агрегирует все фазы одного эпизода. У full, raw, rate, cursor и вариантов Qwen такие повторы возникали при смене этапа. Внутри одной фазы у них повторов не было. Независимый аудит и инструкции по воспроизведению — audit_ru.md и REPLAY_RU.md.'])
    (P/'summary_ru.md').write_text('\n'.join(s)+'\n',encoding='utf8')
if __name__=='__main__':main()
